const state = {
  user: {
    name: "Jeet",
    preferences: {
      theme: "dark"
    }
  }
};

// If you need a completely independent copy:
const backup = structuredClone(state);

backup.user.preferences.theme = "light";

console.log(state.user.preferences.theme);  // dark
console.log(backup.user.preferences.theme); // light

// In many frontend updates, a targeted immutable update
// is preferable to cloning the entire state:
const updatedState = {
  ...state,
  user: {
    ...state.user,
    preferences: {
      ...state.user.preferences,
      theme: "light"
    }
  }
};
